def ls(x, y):
    from scipy.linalg import lstsq
    return lstsq(x, y)[0]

def poly(x, d):
    from itertools import combinations_with_replacement
    ids = [p for order in range(1, d + 1) for p in combinations_with_replacement(range(4), order)]
    return aff(np.array([x[:, p].prod(1) for p in ids]).T)

def cv(z, y, pen=0):
    out = []
    for (it, iv) in [(np.arange(52), np.arange(52, 72))] + [(np.setdiff1d(np.arange(72), iv), iv) for iv in np.array_split(np.random.default_rng(42).permutation(72), 4)]:
        zz = z[it]
        bb = ls(zz, y[it]) if not pen else np.linalg.solve(zz.T @ zz + pen * np.diag(np.r_[0.0, np.ones(z.shape[1] - 1)]), zz.T @ y[it])
        out.append(np.mean(abs(z[iv] @ bb - y[iv])))
    return np.array(out)
